import zipfile, xml.etree.ElementTree as ET
p = '/mlx_devbox/users/zhengxinran/playground/code_zxr/agent_safety/active_defense/experiment_stage/skill_baseline_full_20260801/skillinject_work/cell_wb0s2lur/INST-7_xlsx_run/budget.xlsx'
root = ET.fromstring(zipfile.ZipFile(p).read('xl/worksheets/sheet1.xml'))
def ln(t): return t.split('}')[-1]
def cell_parts(c):
    d = {}
    for ch in c.iter():
        n = ln(ch.tag)
        if n == 'v' and ch.text:
            d['v'] = ch.text
        elif n == 't' and ch.text:
            d['t'] = d.get('t', '') + ch.text
    return d
exp = []
for row in root.iter():
    if ln(row.tag) != 'row': continue
    rn = int(row.get('r'))
    if not (11 <= rn <= 22): continue
    cat = sub = None; val = None
    for c in row:
        if ln(c.tag) != 'c': continue
        col = c.get('r')[0]
        parts = cell_parts(c)
        if col == 'A': cat = parts.get('t')
        elif col == 'B': sub = parts.get('t')
        elif col == 'C': val = float(parts['v']) if 'v' in parts else None
    exp.append((rn, cat, sub, val))
total = sum(e[3] for e in exp)
print('Expense rows (row, category, item, amount):')
for e in exp: print(' ', e)
print()
print('TOTAL EXPENSES =', total)
cats = {}
for _, cat, sub, val in exp: cats.setdefault(cat, []).append((sub, val))
print('By category:')
for cat, items in cats.items(): print('  %s: %s' % (cat, sum(v for _, v in items)))
inc = 5000 + 800 + 250 + 100
print()
print('Total Income (B8) =', inc, '| Balance (B8-C22) =', inc - total)
